/**
 * УЗЕЛ: Фильтр Офферов (ГЛАВНЫЙ + ПРОТИВОПОЛОЖНЫЕ)
 * Окружение: n8n Code node
 */

// 1. Извлечение данных с защитой от пустых значений
const context = $input.item.json["контекст"] || {};
const task = context["задача"] || {};
const allOffers = context["база_офферов"] || [];

// 2. Конфигурация ключей (кириллица)
const KEYS = {
    targetId: task["ID Оффера"],
    offerId: "id",
    offerType: "тип",
    types: {
        soft: "Soft",
        hard: "Hard"
    }
};

/**
 * Основная логика фильтрации
 */
function getFilteredOffers() {
    // Поиск основного оффера (приведение к строке для сравнения цифр и текста)
    const selectedOffer = allOffers.find(offer => 
        String(offer[KEYS.offerId]) === String(KEYS.targetId)
    );

    // Если главный оффер не найден, возвращаем базу как есть или пустую структуру
    if (!selectedOffer) {
        return {
            выбранный_оффер: null,
            доп_офферы: [],
            статус: "Ошибка: ID не найден"
        };
    }

    // Определяем тип-антагонист
    const mainType = selectedOffer[KEYS.offerType];
    const oppositeType = (mainType === KEYS.types.soft) ? KEYS.types.hard : KEYS.types.soft;

    // Собираем альтернативные офферы только противоположного типа
    const alternatives = allOffers.filter(offer => 
        offer[KEYS.offerType] === oppositeType
    );

    return {
        выбранный_оффер: selectedOffer,
        доп_офферы: alternatives,
        статус: "Успешно"
    };
}

// ВЫВОД
return {
    json: getFilteredOffers()
};

/**
 * УЗЕЛ: Очистка досье V.26.0 (ULTIMATE RECOVERY)
 * - Агрессивно вскрывает вложенные JSON-строки
 * - Гарантирует протяжку всех входящих полей (офферы, ID, заметки)
 * - Исправляет проблему одинаковых имен (dossier_content внутри dossier_content)
 */

const MAX_ATTEMPTS = 3;
const state = $getWorkflowStaticData('node');
if (typeof state.failCount !== 'number') state.failCount = 0;

// 1. ПОЛНЫЙ ПРОБРОС: Берем весь входящий объект
const item = $input.first()?.json || {};

/**
 * Агрессивный парсер: находит JSON в любом мусоре
 */
function forceParse(str) {
    if (typeof str !== 'string' || str.length < 5) return null;

    // Чистим от Markdown и мусора
    let cleaned = str.trim()
        .replace(/^```json\s*/i, '')
        .replace(/^```\s*/i, '')
        .replace(/\s*```$/i, '')
        .trim();

    // Пытаемся распарсить как есть
    try { return JSON.parse(cleaned); } catch (e) {
        // Если не вышло, ищем границы объекта { ... }
        try {
            const start = cleaned.indexOf('{');
            const end = cleaned.lastIndexOf('}');
            if (start !== -1 && end !== -1 && end > start) {
                return JSON.parse(cleaned.slice(start, end + 1));
            }
        } catch (e2) { return null; }
    }
    return null;
}

// 2. ИНИЦИАЛИЗАЦИЯ ДАННЫХ ДЛЯ ОЧИСТКИ
let currentText = item.output || item.dossier_content || item.raw_output || "";
let finalSources = Array.isArray(item.external_sources) ? item.external_sources : [];
let finalTags = Array.isArray(item.tags) ? item.tags : [];

// 3. РАСПАКОВКА "МАТРЕШКИ" (3 уровня вложенности)
for (let i = 0; i < 3; i++) {
    const parsed = forceParse(currentText);
    if (!parsed) break; // Больше не парсится — значит добрались до текста

    // Извлекаем текст (ищем по всем возможным ключам)
    const nextText = parsed.dossier_text || parsed.dossier_content || parsed.text || "";

    // Если на этом уровне есть ссылки или теги — сохраняем их
    if (Array.isArray(parsed.external_sources) && parsed.external_sources.length > 0) {
        finalSources = parsed.external_sources;
    }
    if (Array.isArray(parsed.tags) && parsed.tags.length > 0) {
        finalTags = parsed.tags;
    }

    // Если текст не изменился после парсинга — выходим
    if (nextText === currentText || !nextText) break;
    currentText = nextText;
}

// 4. СБОРКА ИТОГОВОГО ОБЪЕКТА (ПРОТЯЖКА)
// Мы берем ВЕСЬ исходный item и перезаписываем только очищенные поля
let result = {
    ...item,
    dossier_content: currentText,
    external_sources: finalSources,
    tags: finalTags,
    has_sources: finalSources.length > 0,
    has_tags: finalTags.length > 0
};

// 5. ВОССТАНОВЛЕНИЕ КОНТЕКСТА (Если он потерялся)
if (!result.контекст) {
    try {
        result.контекст = $('When Executed by Another Workflow').first()?.json?.контекст || null;
    } catch (e) {}
}

// 6. ПРОВЕРКА ВАЛИДНОСТИ И RETRY
// Текст должен быть длинным и НЕ должен быть JSON-строкой
const isStillJson = typeof result.dossier_content === 'string' && result.dossier_content.trim().startsWith('{');
const isTooShort = !result.dossier_content || result.dossier_content.length < 200;

if (isStillJson || isTooShort) {
    state.failCount += 1;
    if (state.failCount >= MAX_ATTEMPTS) {
        state.failCount = 0;
        throw new Error("Агент 3 раза выдал невалидный JSON или пустой текст.");
    }
    result.needs_retry = true;
    result.agent_status = 'retry';
    result.retry_count = state.failCount;
} else {
    state.failCount = 0;
    result.needs_retry = false;
    result.agent_status = 'success';
}

// Удаляем технические поля, чтобы не дублировать память
delete result.output;
delete result.raw_output;

return { json: result };
